// Minimal FFmpeg WebAssembly loader (works without external CDN)

window.FFmpeg = {
  load: async function () {
    if (this.loaded) return this.instance;

    const wasmResponse = await fetch("/ffmpeg/ffmpeg-core.wasm");
    const wasmBinary = await wasmResponse.arrayBuffer();

    const module = {
      wasmBinary,
      print: () => {},
      printErr: () => {},
      onRuntimeInitialized: () => {},
    };

    this.instance = await window.createFFmpegCore(module);
    this.loaded = true;
    return this.instance;
  },

  run: async function (args) {
    const ff = await this.load();
    return ff.callMain(args);
  },

  writeFile: async function (name, data) {
    const ff = await this.load();
    ff.FS.writeFile(name, data);
  },

  readFile: async function (name) {
    const ff = await this.load();
    return ff.FS.readFile(name);
  },
};

// Loader for WebAssembly binary
window.createFFmpegCore = function (Module) {
  return new Promise((resolve) => {
    fetch("/ffmpeg/ffmpeg-core.js")
      .then((r) => r.text())
      .then((js) => {
        const fn = new Function("Module", js + ";return Module;");
        resolve(fn(Module));
      });
  });
};
